-- ============================================================
-- Project X - PostgreSQL / Supabase schema
-- ============================================================
-- Paste this file into Supabase SQL Editor and run it.
--
-- Notes:
-- - Uses UUIDs generated by pgcrypto.
-- - Uses Supabase auth.users for authenticated users.
-- - The public.users table mirrors the application's user profile.
-- - All timestamps use timestamptz.
-- ============================================================

begin;

create extension if not exists pgcrypto;

-- ============================================================
-- ENUM TYPES
-- ============================================================

do $$
begin
    create type public.project_status as enum (
        'planned',
        'active',
        'completed',
        'cancelled'
    );
exception
    when duplicate_object then null;
end $$;

do $$
begin
    create type public.goal_type as enum (
        'numeric',
        'boolean',
        'milestone'
    );
exception
    when duplicate_object then null;
end $$;

do $$
begin
    create type public.habit_frequency as enum (
        'daily',
        'weekly',
        'monthly'
    );
exception
    when duplicate_object then null;
end $$;

do $$
begin
    create type public.media_type as enum (
        'image',
        'video',
        'audio',
        'document'
    );
exception
    when duplicate_object then null;
end $$;

-- ============================================================
-- USERS
-- ============================================================
-- Supabase Auth is the source of truth for authentication.
-- id references auth.users(id).

create table if not exists public.users (
    id uuid primary key references auth.users(id) on delete cascade,
    username varchar(50) not null unique,
    email varchar(255) not null unique,
    display_name varchar(100),
    avatar_url text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

-- ============================================================
-- PROJECTS
-- ============================================================

create table if not exists public.projects (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references public.users(id) on delete cascade,
    name varchar(100) not null,
    description text,
    start_date date not null,
    end_date date not null,
    status public.project_status not null default 'planned',
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    constraint projects_dates_check
        check (end_date >= start_date)
);

-- ============================================================
-- CATEGORIES
-- ============================================================

create table if not exists public.categories (
    id uuid primary key default gen_random_uuid(),
    name varchar(50) not null unique,
    description text,
    icon varchar(50),
    is_default boolean not null default true,
    created_at timestamptz not null default now()
);

-- ============================================================
-- PROJECT <-> CATEGORY
-- ============================================================

create table if not exists public.project_categories (
    project_id uuid not null references public.projects(id) on delete cascade,
    category_id uuid not null references public.categories(id) on delete cascade,
    position integer not null default 0,

    primary key (project_id, category_id),

    constraint project_categories_position_check
        check (position >= 0)
);

-- ============================================================
-- GOALS
-- ============================================================

create table if not exists public.goals (
    id uuid primary key default gen_random_uuid(),
    project_id uuid not null references public.projects(id) on delete cascade,
    category_id uuid not null references public.categories(id) on delete restrict,

    title varchar(150) not null,
    description text,

    goal_type public.goal_type not null default 'numeric',
    unit varchar(30),

    minimum_value numeric,
    target_value numeric,
    bonus_value numeric,

    deadline date,

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    constraint goals_values_non_negative_check
        check (
            (minimum_value is null or minimum_value >= 0)
            and
            (target_value is null or target_value >= 0)
            and
            (bonus_value is null or bonus_value >= 0)
        ),

    constraint goals_target_order_check
        check (
            target_value is null
            or minimum_value is null
            or target_value >= minimum_value
        ),

    constraint goals_bonus_order_check
        check (
            bonus_value is null
            or target_value is null
            or bonus_value >= target_value
        )
);

-- ============================================================
-- GOAL LOGS
-- ============================================================

create table if not exists public.goal_logs (
    id uuid primary key default gen_random_uuid(),
    goal_id uuid not null references public.goals(id) on delete cascade,
    value numeric not null default 0,
    note text,
    logged_at timestamptz not null default now(),
    created_at timestamptz not null default now(),

    constraint goal_logs_value_check
        check (value >= 0)
);

-- ============================================================
-- HABITS
-- ============================================================

create table if not exists public.habits (
    id uuid primary key default gen_random_uuid(),
    project_id uuid not null references public.projects(id) on delete cascade,
    category_id uuid not null references public.categories(id) on delete restrict,

    name varchar(150) not null,
    description text,

    frequency public.habit_frequency not null default 'daily',
    target_count integer,

    unit varchar(30),

    start_date date not null,
    end_date date,

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    constraint habits_target_count_check
        check (target_count is null or target_count > 0),

    constraint habits_dates_check
        check (end_date is null or end_date >= start_date)
);

-- ============================================================
-- HABIT LOGS
-- ============================================================

create table if not exists public.habit_logs (
    id uuid primary key default gen_random_uuid(),
    habit_id uuid not null references public.habits(id) on delete cascade,
    date date not null,
    value numeric not null default 1,
    note text,
    created_at timestamptz not null default now(),

    constraint habit_logs_value_check
        check (value >= 0),

    constraint habit_logs_unique_day
        unique (habit_id, date)
);

-- ============================================================
-- MILESTONES
-- ============================================================

create table if not exists public.milestones (
    id uuid primary key default gen_random_uuid(),
    project_id uuid not null references public.projects(id) on delete cascade,

    title varchar(150) not null,
    description text,

    target_date date,
    completed_at timestamptz,

    created_at timestamptz not null default now()
);

-- ============================================================
-- JOURNAL ENTRIES
-- ============================================================

create table if not exists public.journal_entries (
    id uuid primary key default gen_random_uuid(),
    project_id uuid not null references public.projects(id) on delete cascade,

    title varchar(150),
    content text not null,

    mood smallint,

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    constraint journal_entries_mood_check
        check (mood is null or (mood between 1 and 10))
);

-- ============================================================
-- PROJECT CHECK-INS
-- ============================================================

create table if not exists public.project_checkins (
    id uuid primary key default gen_random_uuid(),
    project_id uuid not null references public.projects(id) on delete cascade,

    date date not null,

    mood smallint,
    energy smallint,
    motivation smallint,

    reflection text,

    created_at timestamptz not null default now(),

    constraint project_checkins_mood_check
        check (mood is null or (mood between 1 and 10)),

    constraint project_checkins_energy_check
        check (energy is null or (energy between 1 and 10)),

    constraint project_checkins_motivation_check
        check (motivation is null or (motivation between 1 and 10)),

    constraint project_checkins_unique_day
        unique (project_id, date)
);

-- ============================================================
-- MEDIA
-- ============================================================

create table if not exists public.media (
    id uuid primary key default gen_random_uuid(),

    user_id uuid not null references public.users(id) on delete cascade,
    project_id uuid not null references public.projects(id) on delete cascade,
    goal_id uuid references public.goals(id) on delete set null,

    type public.media_type not null,
    url text not null,

    title varchar(150),
    description text,

    created_at timestamptz not null default now()
);

-- ============================================================
-- ACHIEVEMENTS
-- ============================================================

create table if not exists public.achievements (
    id uuid primary key default gen_random_uuid(),

    name varchar(100) not null unique,
    description text not null,
    icon varchar(50),

    requirement_type varchar(50) not null,
    requirement_value numeric,

    created_at timestamptz not null default now()
);

-- ============================================================
-- USER ACHIEVEMENTS
-- ============================================================

create table if not exists public.user_achievements (
    user_id uuid not null references public.users(id) on delete cascade,
    achievement_id uuid not null references public.achievements(id) on delete cascade,
    project_id uuid references public.projects(id) on delete set null,

    unlocked_at timestamptz not null default now(),

    primary key (user_id, achievement_id)
);

-- ============================================================
-- PROJECT TEMPLATES
-- ============================================================

create table if not exists public.project_templates (
    id uuid primary key default gen_random_uuid(),

    name varchar(100) not null,
    description text,

    duration_days integer,

    created_by uuid references public.users(id) on delete set null,

    is_public boolean not null default false,

    created_at timestamptz not null default now(),

    constraint project_templates_duration_check
        check (duration_days is null or duration_days > 0)
);

-- ============================================================
-- NOTIFICATIONS
-- ============================================================

create table if not exists public.notifications (
    id uuid primary key default gen_random_uuid(),

    user_id uuid not null references public.users(id) on delete cascade,

    type varchar(50) not null,
    title varchar(150) not null,
    message text not null,

    scheduled_at timestamptz,
    read_at timestamptz,

    created_at timestamptz not null default now()
);

