-- ============================================================
-- ROW LEVEL SECURITY (RLS)
-- ============================================================
-- Security model:
-- - Users can only read/update their own profile.
-- - Users can only access their own projects and data belonging
--   to those projects.
-- - Categories are readable by everyone, but only default/system
--   categories are protected from user-side writes.
-- - Public project templates can be read by everyone.
-- - Private templates are visible only to their creator.
-- - Achievements are readable by everyone.
-- - User achievements are private to the owning user.
-- - Notifications are private to the owning user.
-- ============================================================

-- Helper functions
create or replace function public.is_project_owner(p_project_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1
        from public.projects
        where id = p_project_id
          and user_id = auth.uid()
    );
$$;

create or replace function public.is_goal_owner(p_goal_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1
        from public.goals g
        join public.projects p on p.id = g.project_id
        where g.id = p_goal_id
          and p.user_id = auth.uid()
    );
$$;

create or replace function public.is_habit_owner(p_habit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1
        from public.habits h
        join public.projects p on p.id = h.project_id
        where h.id = p_habit_id
          and p.user_id = auth.uid()
    );
$$;

-- ============================================================
-- ENABLE RLS
-- ============================================================

alter table public.users enable row level security;
alter table public.projects enable row level security;
alter table public.categories enable row level security;
alter table public.project_categories enable row level security;
alter table public.goals enable row level security;
alter table public.goal_logs enable row level security;
alter table public.habits enable row level security;
alter table public.habit_logs enable row level security;
alter table public.milestones enable row level security;
alter table public.journal_entries enable row level security;
alter table public.project_checkins enable row level security;
alter table public.media enable row level security;
alter table public.achievements enable row level security;
alter table public.user_achievements enable row level security;
alter table public.project_templates enable row level security;
alter table public.notifications enable row level security;

-- ============================================================
-- USERS POLICIES
-- ============================================================

drop policy if exists "Users can view own profile" on public.users;
create policy "Users can view own profile"
on public.users
for select
to authenticated
using (id = auth.uid());

drop policy if exists "Users can insert own profile" on public.users;
create policy "Users can insert own profile"
on public.users
for insert
to authenticated
with check (id = auth.uid());

drop policy if exists "Users can update own profile" on public.users;
create policy "Users can update own profile"
on public.users
for update
to authenticated
using (id = auth.uid())
with check (id = auth.uid());

drop policy if exists "Users can delete own profile" on public.users;
create policy "Users can delete own profile"
on public.users
for delete
to authenticated
using (id = auth.uid());

