-- ============================================================

drop policy if exists "Users can view own checkins" on public.project_checkins;
create policy "Users can view own checkins"
on public.project_checkins
for select
to authenticated
using (public.is_project_owner(project_id));

drop policy if exists "Users can create own checkins" on public.project_checkins;
create policy "Users can create own checkins"
on public.project_checkins
for insert
to authenticated
with check (public.is_project_owner(project_id));

drop policy if exists "Users can update own checkins" on public.project_checkins;
create policy "Users can update own checkins"
on public.project_checkins
for update
to authenticated
using (public.is_project_owner(project_id))
with check (public.is_project_owner(project_id));

drop policy if exists "Users can delete own checkins" on public.project_checkins;
create policy "Users can delete own checkins"
on public.project_checkins
for delete
to authenticated
using (public.is_project_owner(project_id));

-- ============================================================
-- MEDIA POLICIES
-- ============================================================

drop policy if exists "Users can view own media" on public.media;
create policy "Users can view own media"
on public.media
for select
to authenticated
using (user_id = auth.uid());

drop policy if exists "Users can create own media" on public.media;
create policy "Users can create own media"
on public.media
for insert
to authenticated
with check (
    user_id = auth.uid()
    and public.is_project_owner(project_id)
    and (
        goal_id is null
        or public.is_goal_owner(goal_id)
    )
);

drop policy if exists "Users can update own media" on public.media;
create policy "Users can update own media"
on public.media
for update
to authenticated
using (user_id = auth.uid())
with check (
    user_id = auth.uid()
    and public.is_project_owner(project_id)
    and (
        goal_id is null
        or public.is_goal_owner(goal_id)
    )
);

drop policy if exists "Users can delete own media" on public.media;
create policy "Users can delete own media"
on public.media
for delete
to authenticated
using (user_id = auth.uid());

